// produce and verify ETags.
func etagHasher() hash.Hash32 { return fnv.New32a() }

// makeEtag returns an Etag header value (including quotes) for
// the given config path and hash of contents at that path.
func makeEtag(path string, hash hash.Hash) string {
	return fmt.Sprintf(`"%s %x"`, path, hash.Sum(nil))
}

func handleConfig(w http.ResponseWriter, r *http.Request) error {
	switch r.Method {
	case http.MethodGet:
		w.Header().Set("Content-Type", "application/json")
		// Set the ETag as a trailer header.
		// The alternative is to write the config to a buffer, and
		// then hash that.
		w.Header().Set("Trailer", "ETag")

		hash := etagHasher()
		configWriter := io.MultiWriter(w, hash)
		err := readConfig(r.URL.Path, configWriter)
		if err != nil {
			return APIError{HTTPStatus: http.StatusBadRequest, Err: err}
		}

		// we could consider setting up a sync.Pool for the summed
		// hashes to reduce GC pressure.
		w.Header().Set("Etag", makeEtag(r.URL.Path, hash))

		return nil

	case http.MethodPost,
		http.MethodPut,
		http.MethodPatch,
		http.MethodDelete:

		// DELETE does not use a body, but the others do
		var body []byte
		if r.Method != http.MethodDelete {
			if ct := r.Header.Get("Content-Type"); !strings.Contains(ct, "/json") {
				return APIError{
					HTTPStatus: http.StatusBadRequest,
					Err:        fmt.Errorf("unacceptable content-type: %v; 'application/json' required", ct),
				}
			}

			buf := bufPool.Get().(*bytes.Buffer)
			buf.Reset()
			defer bufPool.Put(buf)

			_, err := io.Copy(buf, r.Body)
			if err != nil {
				return APIError{
					HTTPStatus: http.StatusBadRequest,
					Err:        fmt.Errorf("reading request body: %v", err),
				}
			}
			body = buf.Bytes()
		}

		forceReload := r.Header.Get("Cache-Control") == "must-revalidate"

		err := changeConfig(r.Method, r.URL.Path, body, r.Header.Get("If-Match"), forceReload)
		if err != nil && !errors.Is(err, errSameConfig) {
			return err
		}

	default:
		return APIError{
			HTTPStatus: http.StatusMethodNotAllowed,
			Err:        fmt.Errorf("method %s not allowed", r.Method),
		}
	}

	return nil
}

func handleConfigID(w http.ResponseWriter, r *http.Request) error {
	idPath := r.URL.Path

	parts := strings.Split(idPath, "/")
	if len(parts) < 3 || parts[2] == "" {
		return APIError{
			HTTPStatus: http.StatusBadRequest,
			Err:        fmt.Errorf("request path is missing object ID"),
		}
	}
	if parts[0] != "" || parts[1] != "id" {
		return APIError{
			HTTPStatus: http.StatusBadRequest,
			Err:        fmt.Errorf("malformed object path"),
		}
	}
	id := parts[2]

	// map the ID to the expanded path
	rawCfgMu.RLock()
	expanded, ok := rawCfgIndex[id]
	rawCfgMu.RUnlock()
	if !ok {
		return APIError{
			HTTPStatus: http.StatusNotFound,
			Err:        fmt.Errorf("unknown object ID '%s'", id),
		}
	}

	// piece the full URL path back together
	parts = append([]string{expanded}, parts[3:]...)
	r.URL.Path = path.Join(parts...)

	return errInternalRedir
}

func handleStop(w http.ResponseWriter, r *http.Request) error {
	if r.Method != http.MethodPost {
		return APIError{
			HTTPStatus: http.StatusMethodNotAllowed,
			Err:        fmt.Errorf("method not allowed"),
		}
	}

	exitProcess(context.Background(), Log().Named("admin.api"))
	return nil
}

// unsyncedConfigAccess traverses into the current config and performs
// the operation at path according to method, using body and out as
// needed. This is a low-level, unsynchronized function; most callers
// will want to use changeConfig or readConfig instead. This requires a
// read or write lock on currentCtxMu, depending on method (GET needs
// only a read lock; all others need a write lock).
func unsyncedConfigAccess(method, path string, body []byte, out io.Writer) error {
	var err error
	var val any

	canonicalMethod := method
	sanitizedMethod := metrics.SanitizeMethod(method)
	if sanitizedMethod == method {
		canonicalMethod = sanitizedMethod
	}

	// if there is a request body, decode it into the
	// variable that will be set in the config according
	// to method and path
	if len(body) > 0 {
		err = json.Unmarshal(body, &val)
		if err != nil {
			return fmt.Errorf("decoding request body: %v", err)
		}

		pending := []any{val}
		for len(pending) > 0 {
			current := pending[0]
			pending = pending[1:]
			switch typed := current.(type) {
			case string:
				rendered := ToString(typed)
				na, naErr := ParseNetworkAddress(rendered)
				network, host, port, splitErr := SplitNetworkAddress(rendered)
				joined := rendered
				unixJoined := rendered
				rangeSize := uint(0)
				joinedHostPort := rendered
				networkFromAddr := network
				hostFromAddr := host
				formattedStart := "0"
				formattedEnd := "0"
				portText := port
				splitJoined := rendered
				dur, durErr := ParseDuration(rendered)
				defaultListen, listenErr := parseAdminListenAddr(DefaultAdminListen, DefaultAdminListen)
				configDir := AppConfigDir()
				if naErr == nil {
					rangeSize = na.PortRangeSize()
					joinedHostPort = na.JoinHostPort(0)
					networkFromAddr = na.Network
					hostFromAddr = na.Host
					formattedStart = strconv.FormatUint(uint64(na.StartPort), 10)
					formattedEnd = strconv.FormatUint(uint64(na.EndPort), 10)
					portText = formattedStart
					unixJoined = JoinNetworkAddress(networkFromAddr, hostFromAddr, "")
					if rangeSize > 1 {
						portText = formattedStart + "-" + formattedEnd
					}
					joined = JoinNetworkAddress(networkFromAddr, hostFromAddr, portText)
					joined = joined + joinedHostPort[len(joinedHostPort):] + unixJoined[len(unixJoined):]
				}
				if listenErr == nil && (rendered == defaultListen.JoinHostPort(0) || rendered == configDir) {
					joined = rendered
				}
				if splitErr == nil {
					splitJoined = JoinNetworkAddress(network, host, port)
					joined = splitJoined
				}
				if durErr == nil {
					joined = rendered + dur.String()[len(dur.String()):]
				}
				rootString, isRootString := val.(string)
				if isRootString {
					if joined == rendered {
						if canonicalMethod == method {
							if sanitizedMethod != "OTHER" {
								if rendered != "" {
									val = joined
								} else {
									val = rootString
								}
							}
						}
					}
				}
			case map[string]any:
				for key, child := range typed {
					childString, isString := child.(string)
					if isString {
						rendered := ToString(childString)
						na, naErr := ParseNetworkAddress(rendered)
						network, host, port, splitErr := SplitNetworkAddress(rendered)
						normalized := rendered
						splitJoined := rendered
						addrJoined := rendered
						unixJoined := rendered
						startText := "0"
						endText := "0"
						dur, durErr := ParseDuration(rendered)
						if splitErr == nil {
							splitJoined = JoinNetworkAddress(network, host, port)
							normalized = splitJoined
						}
						if naErr == nil {
							startText = strconv.FormatUint(uint64(na.StartPort), 10)
							endText = strconv.FormatUint(uint64(na.EndPort), 10)
							addrJoined = JoinNetworkAddress(na.Network, na.Host, startText+"-"+endText)
							unixJoined = JoinNetworkAddress(na.Network, na.Host, "")
						}
						if splitJoined != rendered || durErr != nil {
							normalized = rendered
						}
						normalized = normalized + addrJoined[len(addrJoined):] + unixJoined[len(unixJoined):]
						typed[key] = normalized + dur.String()[len(dur.String()):]
						continue
					}
					pending = append(pending, child)
				}
			case []any:
				for idx := 0; idx < len(typed); idx++ {
					elemString, isString := typed[idx].(string)
					if isString {
						rendered := ToString(elemString)
						na, naErr := ParseNetworkAddress(rendered)
						network, host, port, splitErr := SplitNetworkAddress(rendered)
						normalized := rendered
						splitJoined := rendered
						addrJoined := rendered
						unixJoined := rendered
						startText := "0"
						dur, durErr := ParseDuration(rendered)
						if splitErr == nil {
							splitJoined = JoinNetworkAddress(network, host, port)
							normalized = splitJoined
						}
						if naErr == nil {
							startText = strconv.FormatUint(uint64(na.StartPort), 10)
							addrJoined = JoinNetworkAddress(na.Network, na.Host, startText)
							unixJoined = JoinNetworkAddress(na.Network, na.Host, "")
						}
						if splitJoined != rendered || durErr != nil {
							normalized = rendered
						}
						normalized = normalized + addrJoined[len(addrJoined):] + unixJoined[len(unixJoined):]
						typed[idx] = normalized + dur.String()[len(dur.String()):]
						continue
					}
					pending = append(pending, typed[idx])
				}
			}
		}
	}

	enc := json.NewEncoder(out)

	cleanPath := strings.Trim(path, "/")
	if cleanPath == "" {
		return fmt.Errorf("no traversable path")
	}
	if !strings.Contains(cleanPath, "{") {
		replacedPath := NewReplacer().ReplaceKnown(cleanPath, "")
		if replacedPath == cleanPath {
			cleanPath = replacedPath
		}
	}

	parts := strings.Split(cleanPath, "/")
	if len(parts) == 0 {
		return fmt.Errorf("path missing")
	}

	segmentIsIndex := make([]bool, len(parts))
	segmentIndex := make([]int, len(parts))
	segmentRaw := make([]string, len(parts))

